<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/database.php';
final class Report
{
    private static function range(array $filters,string $column='created_at'): array { $where=[];$p=[];if(!empty($filters['from'])){$where[]="$column>=:from";$p['from']=$filters['from'].' 00:00:00';}if(!empty($filters['to'])){$where[]="$column<=:to";$p['to']=$filters['to'].' 23:59:59';}return [$where,$p]; }
    public static function dashboard(): array { $q=database();return ['total_members'=>(int)$q->query('SELECT COUNT(*) FROM members')->fetchColumn(),'active_members'=>(int)$q->query("SELECT COUNT(*) FROM members WHERE membership_status='ACTIVE'")->fetchColumn(),'upcoming_events'=>(int)$q->query("SELECT COUNT(*) FROM events WHERE event_status='PUBLISHED' AND start_datetime>=NOW()")->fetchColumn(),'pending_services'=>(int)$q->query("SELECT COUNT(*) FROM service_requests WHERE status IN ('PENDING','PENDING_ASSIGNMENT','UNDER_REVIEW','DOCUMENTS_REQUIRED')")->fetchColumn(),'upcoming_appointments'=>(int)$q->query("SELECT COUNT(*) FROM appointments WHERE status IN ('PENDING','CONFIRMED') AND start_datetime>=NOW()")->fetchColumn(),'event_registrations'=>(int)$q->query("SELECT COUNT(*) FROM event_registrations WHERE registration_status='REGISTERED'")->fetchColumn(),'attendance'=>(int)$q->query("SELECT COUNT(*) FROM attendance_records WHERE attendance_status='PRESENT'")->fetchColumn()]; }
    public static function serviceSummary(array $filters): array { [$w,$p]=self::range($filters,'sr.created_at');if(!empty($filters['service_type_id'])){$w[]='sr.service_type_id=:service_type_id';$p['service_type_id']=(int)$filters['service_type_id'];}$where=$w?'WHERE '.implode(' AND ',$w):'';$q=database()->prepare("SELECT st.name,COUNT(*) total,SUM(sr.status='COMPLETED') completed,SUM(sr.status IN ('PENDING','PENDING_ASSIGNMENT','UNDER_REVIEW','DOCUMENTS_REQUIRED')) pending FROM service_requests sr INNER JOIN service_types st ON st.id=sr.service_type_id $where GROUP BY st.id ORDER BY st.name");$q->execute($p);return $q->fetchAll(); }
    public static function eventSummary(array $filters): array { [$w,$p]=self::range($filters,'e.created_at');if(!empty($filters['category_id'])){$w[]='e.category_id=:category_id';$p['category_id']=(int)$filters['category_id'];}$where=$w?'WHERE '.implode(' AND ',$w):'';$q=database()->prepare("SELECT COUNT(*) total_events,SUM(e.event_status='CANCELLED') cancelled FROM events e $where");$q->execute($p);$base=$q->fetch()?:[];$q=database()->prepare("SELECT COUNT(*) FROM event_registrations er INNER JOIN events e ON e.id=er.event_id $where");$q->execute($p);$base['registrations']=(int)$q->fetchColumn();$q=database()->prepare("SELECT COUNT(*) FROM attendance_records ar INNER JOIN attendance_sessions ats ON ats.id=ar.attendance_session_id INNER JOIN events e ON e.id=ats.event_id $where AND ar.attendance_status='PRESENT'");$q->execute($p);$base['attendance']=(int)$q->fetchColumn();return $base; }
    public static function memberSummary(array $filters): array { [$w,$p]=self::range($filters,'m.created_at');$where=$w?'WHERE '.implode(' AND ',$w):'';$q=database()->prepare("SELECT m.membership_status,COUNT(*) total FROM members m $where GROUP BY m.membership_status ORDER BY m.membership_status");$q->execute($p);return $q->fetchAll(); }
    public static function categories(): array { return database()->query('SELECT id,name FROM event_categories WHERE is_active=1 ORDER BY name')->fetchAll(); }
    public static function serviceTypes(): array { return database()->query('SELECT id,name FROM service_types WHERE is_active=1 AND code NOT IN ("SUNDAY_WORSHIP", "OTHER") ORDER BY name')->fetchAll(); }
}
